//! 📐️ Six explicit CAD parent tables with literal composed handles and complete reference geometry.
use super::CadSnapshot;
use crate::{CadReference,CadNode};
use std::collections::{BTreeMap,BTreeSet};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Projection,Cell,FloatColumn,insert_ieee754,read_binary64,ieee754_is_null}}};
const NUMBERS:&[FloatColumn]=&[FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(10),FloatColumn::Binary64(11),FloatColumn::Binary64(12),FloatColumn::Binary64(13),FloatColumn::Binary64(14),FloatColumn::Binary64(15),FloatColumn::Binary64(18)];
fn ordinal(value:usize)->Result<Cell<'static>,String>{i64::try_from(value).map(Cell::Integer).map_err(|e|e.to_string())}
fn optional(value:Option<f64>)->Cell<'static>{value.map(Cell::Real).unwrap_or(Cell::Null)}
fn slots(value:&CadSnapshot)->[(&'static str,Option<&crate::CadModelChild>);4]{[("shapeModel",value.shape_model.as_ref()),("buildingModel",value.building_model.as_ref()),("energyModel",value.energy_model.as_ref()),("structureClassicModel",value.structure_classic_model.as_ref())]}
fn validate_child<S>(value:&store::ArtifactChild<S>,subset:&str)->Result<(),String>{let d=&value.target.dialect;if d.artifact_kind!="s.stdio.semio"||d.standard!="v1"||d.subset!=subset{return Err("CAD composed child has another model/drawing domain".into())}Ok(())}
fn child_cells<S>(value:&store::ArtifactChild<S>)->[Cell<'_>;5]{let target=&value.target;let d=&target.dialect;[Cell::Text(&value.child_id),Cell::Text(&target.artifact_id),Cell::Text(&d.artifact_kind),Cell::Text(&d.standard),Cell::Text(&d.subset)]}
fn forecast(value:&CadSnapshot,mut checkpoint:impl FnMut(usize)->Result<(),String>)->Result<usize,String>{
 let mut count=1usize;for size in[value.drawings.len(),value.nodes.len(),slots(value).iter().filter(|(_,child)|child.is_some()).count(),value.references_by_model_definition_id.len()]{count=count.checked_add(size).ok_or("CAD semantic row count overflow")?;}checkpoint(count)?;
 for rows in value.references_by_model_definition_id.values(){count=count.checked_add(rows.len()).ok_or("CAD reference row count overflow")?;checkpoint(count)?;}Ok(count)
}
fn project(value:&CadSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
 let mut out=Projection::new(<CadSnapshot as ArtifactSqliteSnapshot>::SQLITE_SCHEMA,control)?;let total=forecast(value,|count|out.check_rows(count))?;out.checkpoint_total(total)?;
 out.insert("cad_document",&[Cell::Text(&value.schema),Cell::Text(&value.id)])?;
 for(slot,child)in slots(value){if let Some(child)=child{validate_child(child,"model")?;let c=child_cells(child);out.insert("cad_model_child",&[Cell::Integer(1),Cell::Text(slot),c[0],c[1],c[2],c[3],c[4]])?;out.checkpoint_total(total)?}}
 for(index,child)in value.drawings.iter().enumerate(){validate_child(child,"drawing")?;let c=child_cells(child);out.insert("cad_drawing_child",&[Cell::Integer(1),ordinal(index)?,c[0],c[1],c[2],c[3],c[4]])?;out.checkpoint_total(total)?;}
 for(key,rows)in &value.references_by_model_definition_id{
  let group=out.insert("cad_reference_group",&[Cell::Integer(1),Cell::Text(key)])?;out.checkpoint_total(total)?;
  for(index,row)in rows.iter().enumerate(){let q=row.orientation.map(|q|q.map(|v|optional(Some(v)))).unwrap_or([Cell::Null;4]);let cells=[Cell::Integer(group),ordinal(index)?,Cell::Text(&row.id),Cell::Text(&row.source_url),Cell::Text(&row.media_kind),Cell::Real(row.origin[0]),Cell::Real(row.origin[1]),Cell::Real(row.origin[2]),Cell::Integer(i64::from(row.orientation.is_some())),q[0],q[1],q[2],q[3],optional(row.scale),Cell::Real(row.width_world),Cell::Integer(i64::from(row.hidden)),Cell::Integer(i64::from(row.locked)),optional(row.opacity)];insert_ieee754(&mut out,"cad_reference",&cells,NUMBERS)?;out.checkpoint_total(total)?;}
 }
 for(index,row)in value.nodes.iter().enumerate(){out.insert("cad_node",&[Cell::Integer(1),ordinal(index)?,Cell::Text(&row.id),Cell::Text(&row.label),Cell::Text(&row.kind)])?;out.checkpoint_total(total)?;}
 out.finish()
}
fn identity(row:&SqliteRow,columns:usize,parent:Option<i64>)->Result<(),String>{if row.rowid<=0||row.values.len()!=columns||row.integer(0)?!=row.rowid||parent.is_some_and(|id|row.integer(1).ok()!=Some(id)){return Err("CAD requires positive complete aliases and exact owning parents".into())}Ok(())}
fn flag(row:&SqliteRow,index:usize)->Result<bool,String>{match row.integer(index)?{0=>Ok(false),1=>Ok(true),_=>Err("CAD boolean is undeclared".into())}}
fn read_optional(row:&SqliteRow,index:usize)->Result<Option<f64>,String>{if ieee754_is_null(row,index,NUMBERS)?{Ok(None)}else{read_binary64(row,index,NUMBERS).map(Some)}}
fn child<S>(row:&SqliteRow,start:usize,subset:&str,native:&mut dsl::NativeDecodeControl<'_>)->Result<store::ArtifactChild<S>,String>{
 let target=store::os_io::ArtifactRef{artifact_id:native.copy_text(row.text(start+1)?)?,dialect:store::io_schema::ArtifactDialect{artifact_kind:native.copy_text(row.text(start+2)?)?,standard:native.copy_text(row.text(start+3)?)?,subset:native.copy_text(row.text(start+4)?)?}};let value=store::ArtifactChild::new(native.copy_text(row.text(start)?)?,target);validate_child(&value,subset)?;Ok(value)
}
fn keyed<'a>(rows:&'a[SqliteRow],columns:usize,parent:Option<i64>,native:&mut dsl::NativeDecodeControl<'_>)->Result<BTreeMap<i64,&'a SqliteRow>,String>{
 let mut result=BTreeMap::new();native.begin_stage(rows.len())?;for row in rows{native.step()?;identity(row,columns,parent)?;if result.insert(row.rowid,row).is_some(){return Err("CAD SQL aliases must be unique".into())}}native.checkpoint()?;Ok(result)
}
fn ordered<'a>(rows:impl IntoIterator<Item=&'a SqliteRow>,count:usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,String>{
 let mut result=BTreeMap::new();native.begin_stage(count)?;for row in rows{native.step()?;let ordinal=usize::try_from(row.integer(2)?).map_err(|e|e.to_string())?;if ordinal>=count||result.insert(ordinal,row).is_some(){return Err("CAD ordinals must be unique and contiguous".into())}}if result.len()!=count{return Err("CAD ordered relationship is incomplete".into())}let mut output=native.allocate_vec(count)?;output.extend(result.into_values());native.checkpoint()?;Ok(output)
}
fn restore(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<CadSnapshot,String>{
 validate_sqlite_database_schema(database,<CadSnapshot as ArtifactSqliteSnapshot>::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
 let count=database.tables.iter().try_fold(0usize,|sum,table|sum.checked_add(table.rows.len()).ok_or("CAD row count overflow"))?;let maximum=control.limits().max_value_bytes;let mut progress=|event:semio_framework_value::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,event.completed,event.total).is_ok();let mut native=dsl::NativeDecodeControl::new(maximum,&mut progress);native.charge(count.checked_mul(512).ok_or("CAD workspace byte count overflow")?.checked_add(std::mem::size_of::<CadSnapshot>()).ok_or("CAD root byte count overflow")?)?;
 let documents=&database.table("cad_document")?.rows;if documents.len()!=1||documents[0].rowid!=1{return Err("CAD requires one document".into())}let doc=&documents[0];identity(doc,3,None)?;
 let models=keyed(&database.table("cad_model_child")?.rows,8,Some(1),&mut native)?;let drawings=keyed(&database.table("cad_drawing_child")?.rows,8,Some(1),&mut native)?;let groups=keyed(&database.table("cad_reference_group")?.rows,3,Some(1),&mut native)?;let references=keyed(&database.table("cad_reference")?.rows,39,None,&mut native)?;let nodes=keyed(&database.table("cad_node")?.rows,6,Some(1),&mut native)?;
 let mut value=CadSnapshot{schema:native.copy_text(doc.text(1)?)?,id:native.copy_text(doc.text(2)?)?,shape_model:None,building_model:None,energy_model:None,structure_classic_model:None,drawings:Vec::new(),references_by_model_definition_id:BTreeMap::new(),nodes:Vec::new()};
 let mut slots=BTreeSet::new();for row in models.values(){let slot=row.text(2)?;if !slots.insert(slot){return Err("CAD model slots must be unique".into())}let child=child(row,3,"model",&mut native)?;match slot{"shapeModel"=>value.shape_model=Some(child),"buildingModel"=>value.building_model=Some(child),"energyModel"=>value.energy_model=Some(child),"structureClassicModel"=>value.structure_classic_model=Some(child),_=>return Err("CAD model slot is undeclared".into())}}
 let drawing_rows=ordered(drawings.values().copied(),drawings.len(),&mut native)?;value.drawings=native.allocate_vec(drawing_rows.len())?;native.begin_stage(drawing_rows.len())?;for row in drawing_rows{native.step()?;value.drawings.push(child(row,3,"drawing",&mut native)?);}native.checkpoint()?;
 let mut grouped:BTreeMap<i64,Vec<&SqliteRow>>=BTreeMap::new();native.begin_stage(references.len())?;for row in references.values(){native.step()?;let parent=row.integer(1)?;if !groups.contains_key(&parent){return Err("CAD reference has no owning map group".into())}grouped.entry(parent).or_default().push(row)}native.checkpoint()?;
 for group in groups.values(){let key=native.copy_text(group.text(2)?)?;if value.references_by_model_definition_id.contains_key(&key){return Err("CAD reference map keys must be unique".into())}let rows=grouped.remove(&group.rowid).unwrap_or_default();let count=rows.len();let rows=ordered(rows,count,&mut native)?;let mut owned=native.allocate_vec(rows.len())?;native.begin_stage(rows.len())?;for row in rows{native.step()?;let present=flag(row,9)?;let q=[read_optional(row,10)?,read_optional(row,11)?,read_optional(row,12)?,read_optional(row,13)?];if q.iter().any(|q|q.is_some()!=present){return Err("CAD orientation presence must match all four numeric fields".into())}owned.push(CadReference{id:native.copy_text(row.text(3)?)?,source_url:native.copy_text(row.text(4)?)?,media_kind:native.copy_text(row.text(5)?)?,origin:[read_binary64(row,6,NUMBERS)?,read_binary64(row,7,NUMBERS)?,read_binary64(row,8,NUMBERS)?],orientation:if present{Some([q[0].unwrap(),q[1].unwrap(),q[2].unwrap(),q[3].unwrap()])}else{None},scale:read_optional(row,14)?,width_world:read_binary64(row,15,NUMBERS)?,hidden:flag(row,16)?,locked:flag(row,17)?,opacity:read_optional(row,18)?})}native.checkpoint()?;value.references_by_model_definition_id.insert(key,owned);}
 if !grouped.is_empty(){return Err("CAD has unconsumed references".into())}let rows=ordered(nodes.values().copied(),nodes.len(),&mut native)?;value.nodes=native.allocate_vec(rows.len())?;native.begin_stage(rows.len())?;for row in rows{native.step()?;value.nodes.push(CadNode{id:native.copy_text(row.text(3)?)?,label:native.copy_text(row.text(4)?)?,kind:native.copy_text(row.text(5)?)?})}native.checkpoint()?;Ok(value)
}
fn native_list(value:Option<&dsl::FieldValue>)->Result<&[dsl::FieldValue],dsl::TextError>{match value{None|Some(dsl::FieldValue::Absent)=>Ok(&[]),Some(dsl::FieldValue::List(value))=>Ok(value),_=>Err(dsl::__rt::field_error("CAD requires an ordered native collection"))}}
fn native_rows(record:&dsl::RecordValue,native:&mut dsl::NativeDecodeControl<'_>,maximum:usize)->Result<(),dsl::TextError>{
 let error=||dsl::__rt::field_error("CAD native semantic rows exceed caller limit");let mut count=1usize;let mut add=|size:usize|{count=count.checked_add(size).filter(|count|*count<=maximum).ok_or_else(error)?;Ok::<(),dsl::TextError>(())};
 for id in[2,3,4,5]{if !matches!(record.fields.get(&id),None|Some(dsl::FieldValue::Absent)){add(1)?}}add(native_list(record.fields.get(&6))?.len())?;add(native_list(record.fields.get(&8))?.len())?;
 let groups=match record.fields.get(&7){None|Some(dsl::FieldValue::Absent)=>&[][..],Some(dsl::FieldValue::Map(groups))=>groups.as_slice(),_=>return Err(dsl::__rt::field_error("CAD requires its literal native reference map"))};add(groups.len())?;native.scoped_stage(|native|{native.begin_stage(groups.len()).map_err(dsl::__rt::field_error)?;for(_,value)in groups{native.step().map_err(dsl::__rt::field_error)?;add(native_list(Some(value))?.len())?;}native.checkpoint().map_err(dsl::__rt::field_error)})?;
 Ok(())
}
impl ArtifactSqliteSnapshot for CadSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{project(self,control)}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{restore(database,control)}
 fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{control.check_rows(1)?;let maximum=control.limits().max_rows;store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record,native|{native_rows(record,native,maximum)?;let value=Self::__dsl_from_record_controlled(record,native)?;for(_,child)in slots(&value){if let Some(child)=child{validate_child(child,"model").map_err(dsl::__rt::field_error)?}}for child in &value.drawings{validate_child(child,"drawing").map_err(dsl::__rt::field_error)?}Ok(value)},control)}
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,String>{control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;forecast(self,|count|control.check_rows(count))?;for(_,child)in slots(self){if let Some(child)=child{validate_child(child,"model")?}}for child in &self.drawings{validate_child(child,"drawing")?}store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native),control)}
}
